def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = dict(jumps)
    destination = list(range(n + 1))

    for cell in jump:
        path = []
        current = cell
        while current in jump and destination[current] == current:
            path.append(current)
            current = jump[current]
        final = destination[current]
        for position in path:
            destination[position] = final

    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    reachable = {0}
    queue = deque([0])

    while queue:
        cell = queue.popleft()
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            landing = destination[landing]
            counts[landing] = counts.get(landing, 0) + 1

        transitions[cell] = counts
        for landing in counts:
            reverse[landing].append(cell)
            if landing not in reachable:
                reachable.add(landing)
                queue.append(landing)

    can_finish = {n}
    queue = deque([n])
    while queue:
        cell = queue.popleft()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                queue.append(previous)

    if not reachable.issubset(can_finish):
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell in states:
        row = index[cell]
        matrix[row][row] = m
        matrix[row][size] = m
        for landing, count in transitions[cell].items():
            if landing != n:
                matrix[row][index[landing]] -= count

    previous_pivot = 1
    for col in range(size - 1):
        pivot = matrix[col][col]
        for row in range(col + 1, size):
            factor = matrix[row][col]
            for j in range(col + 1, size + 1):
                matrix[row][j] = (
                    matrix[row][j] * pivot - factor * matrix[col][j]
                ) // previous_pivot
            matrix[row][col] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for row in range(size - 1, -1, -1):
        value = Fraction(matrix[row][size])
        for col in range(row + 1, size):
            value -= matrix[row][col] * solution[col]
        solution[row] = value / matrix[row][row]

    answer = solution[index[0]]
    return [answer.numerator, answer.denominator]
